function renderAll(): Record<string, string> {
  const out: Record<string, string> = {};
  const r = (k: string, el: ReturnType<typeof h>) => {
    out[k] = renderToStaticMarkup(el);
  };
  for (const size of SIZES) {
    r(`booleanCheckbox:${size}`, h(BooleanCheckboxInput, { name: "c", value: true, onChange: noop, size }));
    r(`booleanRadioGroup:${size}`, h(BooleanRadioGroupInput, { name: "r", value: true, onChange: noop, size }));
    r(`singleCardCheckbox:${size}:off`, h(SingleCardCheckbox, { id: "s", value: false, onChange: noop, label: "L", size }));
    r(`singleCardCheckbox:${size}:on`, h(SingleCardCheckbox, { id: "s", value: true, onChange: noop, label: "L", size, checkedVariant: "primary" }));
    r(`switchInput:${size}:off`, h(SwitchInput, { id: "w", value: false, onChange: noop, size }));
    r(`switchInput:${size}:on`, h(SwitchInput, { id: "w", value: true, onChange: noop, size, activeColor: "success", inactiveColor: "warning" }));
  }
  for (const size of STEPPER_SIZES) r(`stepperInput:${size}`, h(StepperInput, { id: "n", value: 1, onValueChange: noop, size }));
  return out;
}

test("上書きが空なら 5 つの入力部品の描画は前と同じ", () => {
  reset();
  assert.deepEqual(renderAll(), BEFORE);
});

test("booleanCheckbox: base と size の上書きがチェックボックスに付く", () => {
  reset();
  Object.assign(OV.booleanCheckbox, { base: "ov-base", size: { lg: "ov-lg" } });
  const lg = renderToStaticMarkup(h(BooleanCheckboxInput, { name: "c", value: true, onChange: noop, size: "lg" }));
  const md = renderToStaticMarkup(h(BooleanCheckboxInput, { name: "c", value: true, onChange: noop }));
  assert.match(lg, /class="[^"]*ov-base[^"]*ov-lg/);
  assert.match(md, /ov-base/);
  assert.doesNotMatch(md, /ov-lg/);
});

test("booleanRadioGroup: base と size の上書きが各ラジオに付く", () => {
  reset();
  Object.assign(OV.booleanRadioGroup, { base: "ov-base", size: { sm: "ov-sm" } });
  const html = renderToStaticMarkup(h(BooleanRadioGroupInput, { name: "r", value: true, onChange: noop, size: "sm" }));
  assert.equal(html.match(/ov-base ov-sm/g)?.length, 2);
});

test("singleCardCheckbox: base・size と、今の色(チェック時 checkedVariant / 未チェック時 uncheckedVariant)の color", () => {
  reset();
  Object.assign(OV.singleCardCheckbox, { base: "ov-base", size: { sm: "ov-sm" }, color: { primary: "ov-primary", muted: "ov-muted" } });
  const on = renderToStaticMarkup(h(SingleCardCheckbox, { id: "s", value: true, onChange: noop, label: "L", size: "sm", checkedVariant: "primary" }));
  const off = renderToStaticMarkup(h(SingleCardCheckbox, { id: "s", value: false, onChange: noop, label: "L", size: "sm", checkedVariant: "primary" }));
  assert.match(on, /ov-base ov-sm/);
  assert.match(on, /ov-primary/);
  assert.doesNotMatch(on, /ov-muted/);
  assert.match(off, /ov-muted/);
  assert.doesNotMatch(off, /ov-primary/);
});

test("stepperInput: base と size の上書きが外枠に付く", () => {
  reset();
  Object.assign(OV.stepperInput, { base: "ov-base", size: { m: "ov-m" } });
  const html = renderToStaticMarkup(h(StepperInput, { id: "n", value: 1, onValueChange: noop, size: "m" }));
  assert.match(html, /^<div class="[^"]*ov-base ov-m/);
});

test("switchInput: track の base・size・activeColor(オンの間)・inactiveColor(オフの間)と indicator の base・size", () => {
  reset();
  Object.assign(OV.switchInput.track, {
    base: "ov-track",
    size: { lg: "ov-track-lg" },
    activeColor: { success: "ov-active" },
    inactiveColor: { warning: "ov-inactive" },
  });
  Object.assign(OV.switchInput.indicator, { base: "ov-dot", size: { lg: "ov-dot-lg" } });
  const props = { id: "w", onChange: noop, size: "lg", activeColor: "success", inactiveColor: "warning" } as const;
  const on = renderToStaticMarkup(h(SwitchInput, { ...props, value: true }));
  const off = renderToStaticMarkup(h(SwitchInput, { ...props, value: false }));
  assert.match(on, /<label[^>]*class="[^"]*ov-track ov-track-lg ov-active"/);
  assert.doesNotMatch(on, /ov-inactive/);
  assert.match(off, /<label[^>]*class="[^"]*ov-track ov-track-lg ov-inactive"/);
  assert.doesNotMatch(off, /ov-active/);
  assert.match(on, /<span class="[^"]*ov-dot ov-dot-lg"/);
});
